def handle(app, svc):
    resp = svc.apply(app)
    result = resp.get("result")
    # Fall back to v1 field names if the partner is still on v1
    if result is None:
        outcome = resp.get("decision")
        credit_limit = resp.get("limit", 0)
    else:
        outcome = result.get("outcome")
        credit_limit = result.get("credit_limit", 0)

    if outcome in ("approved", "issue"):
        action = "issue"
        limit = int(credit_limit)
    elif outcome in ("declined", "decline"):
        action = "decline"
        limit = 0
    else:
        # manual_review / refer / anything undecided
        action = "queue_review"
        limit = 0

    # Network referral rule: self_employed above 6000 requested must go to manual
    # review instead of being issued (a decline stays a decline).
    if action == "issue":
        if app.get("employment") == "self_employed" and int(app.get("requested_limit", 0)) > 6000:
            action = "queue_review"
            limit = 0

    return {"action": action, "limit": limit}

